INSERT INTO activity_package_location
    (id_activity_package_location, id_activity_package, custom_setting, id_location, activity_type, detail, status, created_at, created_by)
SELECT m.id_apl, m.id_package, 1, m.id_location, ap.type,
       jsonb_build_object('setting', s.setting, 'idVatRate', 0, 'listIdPromo', '[]'::jsonb),
       3, f.first_sale, 2
FROM (VALUES
    (2, 29, 15), (12, 48, 15), (13, 49, 15), (14, 52, 15),
    (24, 69, 15), (26, 70, 15), (27, 71, 15), (69, 105, 36)
) AS m(id_apl, id_package, id_location)
JOIN activity_package ap ON ap.id_activity_package = m.id_package
JOIN LATERAL (
    SELECT pli.detail::jsonb -> 'setting' AS setting
    FROM payment_location_item pli
    WHERE pli.action = 2 AND pli.id_action = m.id_apl AND (pli.detail::jsonb ? 'setting')
    ORDER BY pli.created_at DESC
    LIMIT 1
) s ON true
JOIN LATERAL (
    SELECT min(pli.created_at) AS first_sale
    FROM payment_location_item pli
    WHERE pli.action = 2 AND pli.id_action = m.id_apl
) f ON true
ON CONFLICT (id_activity_package_location) DO NOTHING;

SELECT setval('activity_package_location_id_activity_package_location_seq',
              (SELECT max(id_activity_package_location) FROM activity_package_location));

COMMIT;
